const $ = (s) => document.querySelector(s);
let token = localStorage.getItem('restaurantos_token') || '';
const state = {
  user:null, settings:{}, menu:[], categories:[], tables:[], orders:[], inventory:[], suppliers:[], expenses:[], payments:[], customers:[], reservations:[], users:[], dashboard:null, discount:0,
  activeView:'dashboard', menuSearch:'', orderStatus:'', inventorySearch:'', reservationDate:new Date().toISOString().slice(0,10), reportFrom:'', reportTo:'', tab:'all', soundEnabled:localStorage.getItem('restaurantos_sound')!=='off', volume:Number(localStorage.getItem('restaurantos_volume')||.6), theme:localStorage.getItem('restaurantos_theme')||'dark', cart:[], lastReadyOrders:new Set(), watcherStarted:false
};
if(state.theme==='light')document.body.classList.add('soft-light');
let audioContext=null;
function ensureAudio(){try{if(!audioContext)audioContext=new (window.AudioContext||window.webkitAudioContext)();if(audioContext.state==='suspended')audioContext.resume();return audioContext}catch(_e){return null}}
function tone(freq=520,duration=.045,type='sine',volume=.035,start=0){if(!state.soundEnabled)return;try{const ctx=ensureAudio();if(!ctx)return;const now=ctx.currentTime+start,osc=ctx.createOscillator(),gain=ctx.createGain();osc.type=type;osc.frequency.setValueAtTime(freq,now);gain.gain.setValueAtTime(.0001,now);gain.gain.exponentialRampToValueAtTime(Math.max(.0001,volume*state.volume),now+.008);gain.gain.exponentialRampToValueAtTime(.0001,now+duration);osc.connect(gain).connect(ctx.destination);osc.start(now);osc.stop(now+duration+.02)}catch(_e){}}
const clickSound=()=>tone(620,.04,'triangle',.03), successSound=()=>{tone(660,.07,'sine',.045);tone(880,.11,'sine',.045,.07)}, orderSound=()=>{tone(540,.11,'sine',.05);tone(720,.12,'sine',.05,.12);tone(980,.16,'triangle',.05,.25)};
if(!window.__rosSoundBound){window.__rosSoundBound=true;document.addEventListener('click',e=>{const el=e.target.closest('button,.tab,.menu-item,.table-card,.action-tile,[role="button"]');if(el&&!el.dataset.noSound)clickSound()},true)}
async function api(path,options={}){const headers={'Content-Type':'application/json',...(options.headers||{})};if(token)headers['X-Session-Token']=token;const res=await fetch(path,{...options,headers});const data=await res.json().catch(()=>({ok:false,error:'Invalid server response'}));if(res.status===401){token='';localStorage.removeItem('restaurantos_token');state.user=null;renderLogin()}if(!res.ok||data.ok===false)throw new Error(data.error||'Request failed');return data}
const money=v=>Number(v||0).toLocaleString('fr-FR',{minimumFractionDigits:2,maximumFractionDigits:2})+' '+(state.settings.currency||'DZD');
const num=v=>Number(v||0).toLocaleString('fr-FR',{maximumFractionDigits:2});
const esc=s=>String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const dateNow=()=>new Date().toLocaleDateString('fr-FR',{weekday:'long',day:'2-digit',month:'short',year:'numeric'});
const timeNow=()=>new Date().toLocaleTimeString('fr-FR',{hour:'2-digit',minute:'2-digit'});
const today=()=>new Date().toISOString().slice(0,10);
const roleCan=(...roles)=>roles.includes(state.user?.role);
const fmtDate=s=>{if(!s)return '—';const d=new Date(String(s).replace(' ','T')+'Z');return isNaN(d)?String(s):d.toLocaleString('fr-FR',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'})};
const statusClass=s=>`status status-${String(s).toLowerCase()}`;
function toast(msg,kind='info'){const t=document.createElement('div');t.className=`toast ${kind}`;t.innerHTML=`<span class="toast-dot"></span><span>${esc(msg)}</span>`;document.body.appendChild(t);setTimeout(()=>{t.classList.add('hide');setTimeout(()=>t.remove(),220)},2600)}
function showModal(html,wide=false){const b=document.createElement('div');b.className='modal-backdrop';b.id='modal';b.innerHTML=`<div class="modal ${wide?'modal-wide':''}">${html}</div>`;document.body.appendChild(b);b.querySelectorAll('[data-close]').forEach(x=>x.onclick=closeModal);b.onclick=e=>{if(e.target===b)closeModal()};}
function closeModal(){document.getElementById('modal')?.remove()}
function applyTheme(){document.body.classList.toggle('soft-light',state.theme==='light');const b=$('#themeToggle');if(b){b.textContent=state.theme==='light'?'☾':'☼';b.title=state.theme==='light'?'Switch to dark theme':'Switch to light theme'}}
function renderLogin(){
  $('#app').innerHTML=`<div class="login-screen"><div class="login-hero"></div><div class="login-overlay"></div><div class="login-card"><div class="brand brand-large"><div class="brand-mark">👨‍🍳</div><div><h1>Restaurant<span>OS</span></h1><small>Smart Restaurant Management</small></div></div><div class="eyebrow" style="margin-top:30px">SECURE LOCAL LOGIN</div><h2>Welcome back</h2><p class="muted">Front of house, kitchen, stock, cash and management in one workspace.</p><form id="loginForm"><div class="field"><label>Email</label><input class="input" id="email" value="admin@restaurantos.local" autocomplete="username" required></div><div class="field"><label>Password</label><div class="password-row"><input class="input" id="password" type="password" value="Admin@123" autocomplete="current-password" required><button type="button" class="btn ghost" id="showPass" data-no-sound>Show</button></div></div><button class="btn primary big" data-no-sound><span>Sign in</span><span>→</span></button></form><div class="login-foot"><span>● Local server</span><span>SQLite</span><span>Role-based access</span></div></div></div>`;
  $('#showPass').onclick=()=>{const p=$('#password');p.type=p.type==='password'?'text':'password';$('#showPass').textContent=p.type==='password'?'Show':'Hide'};
  $('#loginForm').onsubmit=async e=>{e.preventDefault();try{const d=await api('/api/login',{method:'POST',body:JSON.stringify({email:$('#email').value,password:$('#password').value})});token=d.token;state.user=d.user;localStorage.setItem('restaurantos_token',token);successSound();await loadApp()}catch(err){toast(err.message,'error')}};
}
async function loadApp(){const [me,set,menu,tables,dash,customers]=await Promise.all([api('/api/me'),api('/api/settings'),api('/api/menu'),api('/api/tables'),api('/api/dashboard'),api('/api/customers')]);state.user=me.user;state.settings=set.settings;state.categories=menu.categories;state.menu=menu.items;state.tables=tables.tables;state.dashboard=dash;state.customers=customers.customers;renderShell();startOrderWatcher()}
async function refreshCore(){await Promise.all([loadDashboard(),loadMenu(),loadTables()])}
async function loadDashboard(){state.dashboard=await api('/api/dashboard')}
async function loadMenu(){const d=await api('/api/menu');state.menu=d.items;state.categories=d.categories}
async function loadTables(){state.tables=(await api('/api/tables')).tables}
const navItems=[
  ['dashboard','⌂','Dashboard','MAIN'],['pos','🛒','Point of Sale','MAIN'],['orders','🧾','Orders','MAIN'],['kitchen','👨‍🍳','Kitchen','MAIN'],['tables','▦','Tables','MAIN'],['reservations','📅','Reservations','MAIN'],['customers','👥','Customers','MAIN'],
  ['menu','🍽','Menu','OPERATIONS'],['inventory','📦','Inventory','OPERATIONS'],['purchases','🚚','Purchasing','OPERATIONS'],
  ['expenses','💸','Expenses','FINANCE'],['payments','💳','Payments','FINANCE'],['cash','💵','Cash Register','FINANCE'],['debts','📒','Debts','FINANCE'],['reports','▥','Reports','FINANCE'],
  ['staff','🧑‍💼','Staff','SYSTEM'],['audit','🛡','Audit Log','SYSTEM'],['settings','⚙','Settings','SYSTEM']
];
function setView(view){state.activeView=view;document.querySelectorAll('[data-view]').forEach(x=>x.classList.toggle('active',x.dataset.view===view));renderView(view)}
function renderShell(){
  const groups=['MAIN','OPERATIONS','FINANCE','SYSTEM'];
  const nav=groups.map(g=>`<div class="side-label ${g!=='MAIN'?'lower':''}">${g}</div>`+navItems.filter(x=>x[3]===g).map(([v,i,l])=>`<button class="side-link ${v===state.activeView?'active':''}" data-view="${v}"><span class="side-icon">${i}</span><span>${l}</span>${v==='orders'&&state.dashboard?.stats?.open_orders?`<span class="nav-badge">${state.dashboard.stats.open_orders}</span>`:''}${v==='kitchen'&&state.dashboard?.stats?.open_orders?`<span class="nav-badge hot">${state.dashboard.stats.open_orders}</span>`:''}</button>`).join('')).join('');
  $('#app').innerHTML=`<div class="app-shell"><header class="topbar"><div class="top-brand"><div class="brand-mark small">👨‍🍳</div><div><h1>Restaurant<span>OS</span></h1><small>${esc(state.settings.restaurant_name||'Restaurant Management')}</small></div></div><div class="top-center"><div class="search"><span>⌕</span><input id="globalSearch" placeholder="Search orders, menu, customers, stock…"></div></div><div class="top-actions"><div class="clock"><span class="clock-time" id="clockTime">${timeNow()}</span><span class="clock-date" id="clockDate">${dateNow()}</span></div><button class="icon-btn" id="soundToggle" title="Sound">${state.soundEnabled?'🔊':'🔇'}</button><button class="icon-btn" id="themeToggle" title="Theme">☼</button><div class="user-chip"><div class="avatar">${esc((state.user?.display_name||'A')[0].toUpperCase())}</div><div><strong>${esc(state.user?.display_name||'User')}</strong><small>${esc(state.user?.role||'')}</small></div></div><button class="btn ghost logout-btn" id="logout">Logout</button></div></header><div class="app-body"><aside class="sidebar">${nav}<div class="side-spacer"></div><div class="sound-card"><div><strong>Sound System</strong><small>Click & order alerts</small></div><label class="switch"><input id="soundSwitch" type="checkbox" ${state.soundEnabled?'checked':''}><span></span></label><div class="sound-row"><span>Vol</span><input id="volumeRange" type="range" min="0" max="1" step="0.05" value="${state.volume}"></div></div><div class="side-footer"><span class="online-dot"></span>System Online</div></aside><main class="main"><div id="view"></div></main></div></div>`;
  $('#logout').onclick=async()=>{try{await api('/api/logout',{method:'POST'})}catch(_e){}token='';state.user=null;localStorage.removeItem('restaurantos_token');renderLogin()};
  $('#soundToggle').onclick=toggleSound;$('#soundSwitch').onchange=toggleSound;$('#volumeRange').oninput=e=>{state.volume=Number(e.target.value);localStorage.setItem('restaurantos_volume',state.volume)};
  $('#themeToggle').onclick=()=>{state.theme=state.theme==='light'?'dark':'light';localStorage.setItem('restaurantos_theme',state.theme);applyTheme()};applyTheme();
  document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>setView(b.dataset.view));$('#globalSearch').oninput=e=>{state.menuSearch=e.target.value.trim().toLowerCase();renderView(state.activeView)};renderView(state.activeView);
  if(!window.__clockTimer){window.__clockTimer=setInterval(()=>{if($('#clockTime')){$('#clockTime').textContent=timeNow();$('#clockDate').textContent=dateNow()}},1000)}
}
function toggleSound(){state.soundEnabled=!state.soundEnabled;localStorage.setItem('restaurantos_sound',state.soundEnabled?'on':'off');if(state.soundEnabled){ensureAudio();successSound()}$('#soundToggle').textContent=state.soundEnabled?'🔊':'🔇';$('#soundSwitch').checked=state.soundEnabled}
function renderView(v){const fn={dashboard:renderDashboard,pos:renderPOS,orders:renderOrders,kitchen:renderKitchen,tables:renderTables,reservations:renderReservations,customers:renderCustomers,menu:renderMenu,inventory:renderInventory,purchases:renderPurchases,expenses:renderExpenses,payments:renderPayments,cash:renderCash,debts:renderDebts,reports:renderReports,staff:renderStaff,audit:renderAudit,settings:renderSettings}[v];if(fn)Promise.resolve(fn()).catch(e=>toast(e.message,'error'));else renderDashboard()}
function pageHead(eyebrow,title,desc,actions=''){return `<div class="page-head"><div><span class="eyebrow">${eyebrow}</span><h2>${title}</h2><p class="muted">${desc}</p></div><div class="page-head-actions">${actions}</div></div>`}
function renderDashboard(){const s=state.dashboard?.stats||{},top=state.dashboard?.top_items||[],recent=state.dashboard?.recent||[];const net=Number(s.today_sales||0)-Number(s.today_expenses||0);$('#view').innerHTML=`<section class="hero-banner"><div class="hero-copy"><span class="eyebrow">SMART RESTAURANT OPERATIONS</span><h2>Welcome back, <span>${esc(state.user?.display_name||'Manager')}!</span></h2><p>Run service, kitchen, stock and cash from one live workspace.</p><div class="hero-pills"><span>● POS live</span><span>● ${s.open_orders||0} open orders</span><span>● ${s.low_stock||0} low-stock items</span><span>● ${s.customers||0} customers</span></div></div><div class="hero-food"><div class="plate-shadow"></div><div class="hero-dish">🍔</div></div></section><div class="kpis"><div class="kpi-card"><div class="kpi-icon">💰</div><div><span>Sales today</span><strong>${money(s.today_sales)}</strong><small>Paid orders</small></div></div><div class="kpi-card"><div class="kpi-icon">🧾</div><div><span>Orders today</span><strong>${s.today_orders||0}</strong><small>All statuses</small></div></div><div class="kpi-card"><div class="kpi-icon">💸</div><div><span>Expenses today</span><strong>${money(s.today_expenses)}</strong><small>Operating costs</small></div></div><div class="kpi-card"><div class="kpi-icon">📦</div><div><span>Low stock</span><strong>${s.low_stock||0}</strong><small>${s.cash_open?'Cash session open':'Cash session closed'}</small></div></div></div><div class="action-grid"><button class="action-tile tile-order" data-no-sound onclick="setView('pos')"><div class="tile-overlay"></div><div class="tile-content"><span class="tile-icon">🛒</span><div><strong>New Order</strong><small>Start a POS ticket</small></div><span class="arrow">→</span></div></button><button class="action-tile tile-kitchen" data-no-sound onclick="setView('kitchen')"><div class="tile-overlay"></div><div class="tile-content"><span class="tile-icon">👨‍🍳</span><div><strong>Kitchen</strong><small>${s.open_orders||0} live orders</small></div><span class="arrow">→</span></div></button><button class="action-tile tile-menu" data-no-sound onclick="setView('menu')"><div class="tile-overlay"></div><div class="tile-content"><span class="tile-icon">🍽</span><div><strong>Menu</strong><small>Edit products and recipes</small></div><span class="arrow">→</span></div></button><button class="action-tile tile-tables" data-no-sound onclick="setView('cash')"><div class="tile-overlay"></div><div class="tile-content"><span class="tile-icon">💵</span><div><strong>Cash Register</strong><small>Open, reconcile and close</small></div><span class="arrow">→</span></div></button></div><div class="dashboard-grid"><section class="panel"><div class="panel-head"><div><span class="eyebrow">LIVE FEED</span><h3>Recent Orders</h3></div><button class="link-btn" onclick="setView('orders')">View All</button></div>${recent.length?recent.map(o=>`<div class="recent-item"><div class="mini-food ${o.status}">${o.status==='ready'?'✓':'🍽'}</div><div class="recent-main"><strong>#${o.id}</strong><span>${esc(o.table_no||'Takeaway')}</span><small>${fmtDate(o.created_at)}</small></div><div class="recent-end"><span class="${statusClass(o.status)}">${esc(o.status)}</span><strong>${money(o.total)}</strong></div></div>`).join(''):'<div class="empty">No orders yet.</div>'}</section><section class="right-column"><section class="panel"><div class="panel-head"><div><span class="eyebrow">FLOOR STATUS</span><h3>Tables</h3></div><button class="link-btn" onclick="setView('tables')">Manage</button></div><div class="table-status"><div><span class="circle green">${s.available_tables||0}</span><small>Available</small></div><div><span class="circle orange">${s.occupied_tables||0}</span><small>Occupied</small></div><div><span class="circle blue">${s.reserved_tables||0}</span><small>Reserved</small></div></div></section><section class="panel"><div class="panel-head"><div><span class="eyebrow">TOP SELLERS</span><h3>Best items</h3></div></div>${top.length?top.map(x=>`<div class="simple-row"><span>${esc(x.name)}</span><strong>${x.qty}</strong></div>`).join(''):'<div class="empty">Paid orders will build this list.</div>'}</section><section class="panel"><div class="panel-head"><div><span class="eyebrow">TODAY</span><h3>Operating view</h3></div><button class="link-btn" onclick="setView('reports')">Reports</button></div><div class="simple-row"><span>Sales</span><strong>${money(s.today_sales)}</strong></div><div class="simple-row"><span>Expenses</span><strong>${money(s.today_expenses)}</strong></div><div class="simple-row"><span>Net before stock cost</span><strong>${money(net)}</strong></div></section></section></div>`}
function filteredMenu(){return state.menu.filter(m=>!state.menuSearch||`${m.name} ${m.description} ${m.category_name}`.toLowerCase().includes(state.menuSearch))}
function renderPOS(){if(!state.tab)state.tab='all';const cats=`<button class="tab ${state.tab==='all'?'active':''}" data-cat="all">All</button>`+state.categories.map(c=>`<button class="tab ${state.tab===String(c.id)?'active':''}" data-cat="${c.id}">${esc(c.name)}</button>`).join('');const items=filteredMenu().filter(m=>state.tab==='all'||String(m.category_id)===String(state.tab));$('#view').innerHTML=pageHead('POINT OF SALE','Build an order','Fast service with live menu pricing and tax calculation',`<div class="shortcut-hint"><kbd>N</kbd> New order <kbd>Esc</kbd> Clear cart</div>`)+`<div class="pos-layout"><section class="panel menu-panel"><div class="section-head"><div class="tabs">${cats}</div></div><div class="menu-grid">${items.map((m,i)=>`<button class="menu-item photo-item" data-add="${m.id}" style="--delay:${i*20}ms"><span class="food-photo food-${(m.id%6)+1}"></span><div class="menu-item-body"><span class="category-pill">${esc(m.category_name||'Uncategorized')}</span><h4>${esc(m.name)}</h4><div class="desc">${esc(m.description)}</div><div class="price">${money(m.price)}</div></div></button>`).join('')||'<div class="empty">No matching menu items.</div>'}</div></section><aside class="panel order-panel"><div class="section-head"><div><span class="eyebrow">CURRENT CHECK</span><h3>Order ticket</h3></div><button class="btn ghost small" id="clearCart">Clear</button></div><div id="cart" class="order-list"></div><div class="field"><label>Table</label><select class="select" id="orderTable"><option value="">Takeaway / no table</option>${state.tables.map(t=>`<option value="${t.id}">${esc(t.table_no)} · ${esc(t.status)}</option>`).join('')}</select></div><div class="field"><label>Customer</label><select class="select" id="orderCustomer"><option value="">Walk-in / no customer</option>${state.customers.map(c=>`<option value="${c.id}">${esc(c.name)}${c.phone?` · ${esc(c.phone)}`:''}</option>`).join('')}</select></div><div class="field"><label>Discount</label><input class="input" id="orderDiscount" type="number" min="0" step="0.01" value="${Number(state.discount||0)}"></div><div class="total-box" id="totals"></div><button class="btn primary big" id="submitOrder" data-no-sound><span>Send to kitchen</span><span>🔔</span></button></aside></div>`;document.querySelectorAll('[data-cat]').forEach(b=>b.onclick=()=>{state.tab=b.dataset.cat;renderPOS()});document.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>{const id=Number(b.dataset.add),m=state.menu.find(x=>x.id===id),found=state.cart.find(x=>x.menu_item_id===id);if(found)found.quantity++;else state.cart.push({menu_item_id:id,name:m.name,price:Number(m.price),quantity:1});updateCart()});$('#clearCart').onclick=()=>{state.cart=[];state.discount=0;$('#orderDiscount').value='0';updateCart()};$('#orderDiscount').oninput=e=>{state.discount=Math.max(0,Number(e.target.value)||0);updateCart()};$('#submitOrder').onclick=submitOrder;updateCart()}
function updateCart(){const c=$('#cart');if(!c)return;c.innerHTML=state.cart.length?state.cart.map((x,i)=>`<div class="order-row"><div><strong>${esc(x.name)}</strong><div class="muted">${money(x.price)} each</div></div><div class="qty"><button class="btn mini" data-dec="${i}">−</button><b>${x.quantity}</b><button class="btn mini" data-inc="${i}">+</button></div><strong>${money(x.price*x.quantity)}</strong></div>`).join(''):'<div class="empty-order"><span>🍽</span><p>Your order is empty</p><small>Add menu items to start.</small></div>';const subtotal=state.cart.reduce((s,x)=>s+Number(x.price)*x.quantity,0),discount=Math.min(Math.max(Number(state.discount||0),0),subtotal),taxRate=Number(state.settings.tax_rate||0),tax=(subtotal-discount)*taxRate/100,total=subtotal-discount+tax;$('#totals').innerHTML=`<div class="total-line"><span>Subtotal</span><span>${money(subtotal)}</span></div><div class="total-line"><span>Discount</span><span>− ${money(discount)}</span></div><div class="total-line"><span>Tax (${taxRate.toFixed(2)}%)</span><span>${money(tax)}</span></div><div class="total-line grand"><span>Total</span><span>${money(total)}</span></div>`;document.querySelectorAll('[data-inc]').forEach(b=>b.onclick=()=>{state.cart[+b.dataset.inc].quantity++;updateCart()});document.querySelectorAll('[data-dec]').forEach(b=>b.onclick=()=>{const i=+b.dataset.dec;state.cart[i].quantity--;if(state.cart[i].quantity<=0)state.cart.splice(i,1);updateCart()})}
async function submitOrder(){if(!state.cart.length){toast('Add at least one item first','error');return}try{const d=await api('/api/orders',{method:'POST',body:JSON.stringify({table_id:$('#orderTable').value?Number($('#orderTable').value):null,customer_id:$('#orderCustomer')?.value?Number($('#orderCustomer').value):null,customer_name:$('#orderCustomer')?.value?(state.customers.find(c=>c.id===Number($('#orderCustomer').value))?.name||''):($('#customerName')?.value||''),discount:Number(state.discount||0),items:state.cart.map(x=>({menu_item_id:x.menu_item_id,quantity:x.quantity}))})});const oid=d.order_id;state.cart=[];state.discount=0;orderSound();await refreshCore();renderPOS();toast(`Order #${oid} sent to kitchen`,'success')}catch(e){toast(e.message,'error')}}
async function fetchOrder(id){const d=await api(`/api/orders?limit=500`);return d.orders.find(x=>x.id===Number(id))}
async function renderOrders(){await loadOrders();const q=state.menuSearch;const rows=state.orders.filter(o=>(!q||`#${o.id} ${o.table_no||''} ${o.customer_name||''} ${o.status}`.toLowerCase().includes(q))&&(!state.orderStatus||o.status===state.orderStatus));$('#view').innerHTML=pageHead('SERVICE FLOW','Orders','Track order progress, payment and printable receipts',`<button class="btn primary" onclick="setView('pos')">+ New order</button>`)+`<section class="panel"><div class="panel-toolbar"><div class="toolbar-group"><select class="select compact-select" id="orderFilter"><option value="">All statuses</option>${['open','preparing','ready','paid','cancelled'].map(x=>`<option ${state.orderStatus===x?'selected':''}>${x}</option>`).join('')}</select><span class="muted">${rows.length} orders shown</span></div><button class="btn ghost small" id="refreshOrders">Refresh</button></div><div class="orders-table-head"><span>Order</span><span>Items</span><span>Status</span><span>Total</span><span>Actions</span></div><div class="orders-table">${rows.map(o=>`<div class="orders-row"><div><strong>#${o.id}</strong><small>${esc(o.table_no||'Takeaway')} ${o.customer_name?`· ${esc(o.customer_name)}`:''}</small></div><div class="order-items-text">${o.items.map(i=>`${esc(i.name)} × ${i.quantity}`).join(', ')}</div><div><span class="${statusClass(o.status)}">${esc(o.status)}</span></div><div><strong>${money(o.total)}</strong><small class="muted">Paid ${money(o.paid_amount)}</small></div><div class="row-actions"><button class="btn ghost small" data-view-order="${o.id}">View</button>${o.status==='ready'?'<button class="btn primary small" data-pay-order="'+o.id+'">Pay</button>':''}</div></div>`).join('')||'<div class="empty">No orders found.</div>'}</div></section>`;$('#orderFilter').onchange=e=>{state.orderStatus=e.target.value;renderOrders()};$('#refreshOrders').onclick=()=>renderOrders();document.querySelectorAll('[data-view-order]').forEach(b=>b.onclick=()=>openOrderModal(Number(b.dataset.viewOrder),rows));document.querySelectorAll('[data-pay-order]').forEach(b=>b.onclick=()=>openPaymentModal(rows,Number(b.dataset.payOrder)))}
async function loadOrders(){state.orders=(await api('/api/orders?limit=500')).orders}
function openOrderModal(id,orders){const o=orders.find(x=>x.id===id);if(!o)return;const remaining=Math.max(0,Number(o.total)-Number(o.paid_amount||0));showModal(`<div class="modal-top"><div><span class="eyebrow">ORDER #${o.id}</span><h3>${esc(o.table_no||'Takeaway')}</h3></div><button class="icon-btn" data-close>×</button></div><div class="detail-grid"><div><span>Status</span><strong class="${statusClass(o.status)}">${esc(o.status)}</strong></div><div><span>Total</span><strong>${money(o.total)}</strong></div><div><span>Paid</span><strong>${money(o.paid_amount)}</strong></div><div><span>Remaining</span><strong>${money(remaining)}</strong></div></div><div class="receipt-items">${o.items.map(i=>`<div class="simple-row"><span>${esc(i.name)} × ${i.quantity}</span><strong>${money(i.line_total)}</strong></div>`).join('')}</div><div class="modal-actions"><button class="btn ghost" id="printOrder">Print receipt</button>${remaining>0&&o.status==='ready'?'<button class="btn primary" id="collectOrder">Collect payment</button>':''}<button class="btn ghost" data-close>Close</button></div>`);$('#printOrder').onclick=()=>printReceipt(o);$('#collectOrder')?.addEventListener('click',()=>{closeModal();openPaymentModal(orders,o.id)})}
function printReceipt(o){const w=window.open('','_blank','width=420,height=700');if(!w){toast('Popup blocked by browser','error');return}w.document.write(`<!doctype html><html><head><title>Receipt #${o.id}</title><style>body{font-family:Arial,sans-serif;padding:24px;color:#111}.r{text-align:center}.line{border-top:1px dashed #777;margin:10px 0}.row{display:flex;justify-content:space-between;margin:7px 0;font-size:13px}h1{font-size:22px;margin:0 0 6px}small{color:#555}</style></head><body><div class="r"><h1>${esc(state.settings.restaurant_name||'RestaurantOS')}</h1><small>${esc(state.settings.address||'')} ${esc(state.settings.phone||'')}</small><p>Order #${o.id} · ${esc(o.table_no||'Takeaway')}</p></div><div class="line"></div>${o.items.map(i=>`<div class="row"><span>${esc(i.name)} × ${i.quantity}</span><strong>${money(i.line_total)}</strong></div>`).join('')}<div class="line"></div><div class="row"><span>Subtotal</span><strong>${money(o.subtotal)}</strong></div><div class="row"><span>Tax</span><strong>${money(o.tax)}</strong></div><div class="row"><strong>Total</strong><strong>${money(o.total)}</strong></div><div class="line"></div><div class="r"><small>${esc(state.settings.receipt_footer||'Thank you.')}</small></div><script>window.onload=()=>{window.print();setTimeout(()=>window.close(),400)}</script></body></html>`);w.document.close()}
function kitchenNext(status){return status==='open'?'preparing':status==='preparing'?'ready':null}
async function renderKitchen(){const d=await api('/api/kitchen');const groups={open:d.orders.filter(o=>o.status==='open'),preparing:d.orders.filter(o=>o.status==='preparing'),ready:d.orders.filter(o=>o.status==='ready')};$('#view').innerHTML=pageHead('KITCHEN DISPLAY','Kitchen Board','Large, fast service queue for open, preparing and ready tickets',`<button class="btn ghost" id="refreshKitchen">Refresh</button>`)+`<div class="kitchen-board">${Object.entries(groups).map(([status,items])=>`<section class="kitchen-column ${status}"><div class="kitchen-column-head"><div><span class="eyebrow">${status.toUpperCase()}</span><h3>${items.length}</h3></div><span class="status ${statusClass(status)}">${status}</span></div>${items.map(o=>`<article class="kitchen-card"><div class="kitchen-card-top"><strong>#${o.id}</strong><span>${esc(o.table_no||'Takeaway')}</span><small>${fmtDate(o.created_at)}</small></div><div class="kitchen-items">${o.items.map(i=>`<div><b>${i.quantity}×</b><span>${esc(i.name)}</span>${i.notes?`<small>${esc(i.notes)}</small>`:''}</div>`).join('')}</div><div class="kitchen-card-foot"><strong>${money(o.total)}</strong>${kitchenNext(o.status)?`<button class="btn primary small" data-k-next="${o.id}" data-next="${kitchenNext(o.status)}">${kitchenNext(o.status)==='preparing'?'Start':'Ready'}</button>`:o.status==='ready'?`<button class="btn ghost small" data-k-view="${o.id}">View</button>`:''}</div></article>`).join('')||'<div class="empty">Queue clear.</div>'}</section>`).join('')}</div>`;$('#refreshKitchen').onclick=renderKitchen;document.querySelectorAll('[data-k-next]').forEach(b=>b.onclick=async()=>{try{await api('/api/orders/status',{method:'POST',body:JSON.stringify({order_id:Number(b.dataset.kNext),status:b.dataset.next})});await refreshCore();renderKitchen();if(b.dataset.next==='ready')orderSound();else successSound()}catch(e){toast(e.message,'error')}});document.querySelectorAll('[data-k-view]').forEach(b=>b.onclick=()=>setView('orders'))}
function renderTables(){const can=roleCan('admin','manager');$('#view').innerHTML=pageHead('FLOOR PLAN','Dining Tables','Live floor state, reservations and table control',`${can?'<button class="btn primary" id="addTable">+ Add table</button>':''}`)+`<section class="panel"><div class="panel-toolbar"><span class="muted">${state.tables.length} tables</span><div class="legend-row"><span>Available</span><span>Occupied</span><span>Reserved</span><span>Cleaning</span></div></div><div class="tables-grid">${state.tables.map(t=>`<button class="table-card ${esc(t.status)}" data-table="${t.id}"><span class="table-ring"><strong>${esc(t.table_no)}</strong></span><div><strong>${t.seats}</strong><small>seats</small></div><span class="${statusClass(t.status)}">${esc(t.status)}</span></button>`).join('')}</div></section>`;document.querySelectorAll('[data-table]').forEach(x=>x.onclick=()=>openTableModal(+x.dataset.table));$('#addTable')?.addEventListener('click',()=>openTableModal())}
function openTableModal(id=null){const t=id?state.tables.find(x=>x.id===id):{};const canEdit=roleCan('admin','manager');showModal(`<div class="modal-top"><div><span class="eyebrow">TABLE CONTROL</span><h3>${id?`Table ${esc(t.table_no)}`:'New table'}</h3></div><button class="icon-btn" data-close>×</button></div><div class="form-grid"><div class="field"><label>Table number</label><input class="input" id="mTableNo" value="${esc(t.table_no||'')}" ${canEdit?'':'disabled'}></div><div class="field"><label>Seats</label><input class="input" id="mSeats" type="number" min="1" value="${t.seats||4}" ${canEdit?'':'disabled'}></div><div class="field span-2"><label>Status</label><select class="select" id="mStatus">${['available','occupied','reserved','cleaning'].map(x=>`<option ${t.status===x?'selected':''}>${x}</option>`).join('')}</select></div></div><div class="modal-actions">${id&&canEdit?'<button class="btn danger" id="archiveTable">Set cleaning</button>':''}<button class="btn ghost" data-close>Cancel</button><button class="btn primary" id="saveTable">${id?'Save':'Create'}</button></div>`);$('#saveTable').onclick=async()=>{try{if(!$('#mTableNo').value.trim())throw new Error('Table number required');await api('/api/tables',{method:'POST',body:JSON.stringify({id,table_no:$('#mTableNo').value,seats:Number($('#mSeats').value),status:$('#mStatus').value})});await loadTables();closeModal();renderTables();toast(id?'Table updated':'Table created','success')}catch(e){toast(e.message,'error')}};$('#archiveTable')?.addEventListener('click',async()=>{try{await api('/api/tables/delete',{method:'POST',body:JSON.stringify({id})});await loadTables();closeModal();renderTables();toast('Table marked for cleaning','success')}catch(e){toast(e.message,'error')}})}
function renderMenu(){const can=roleCan('admin','manager');$('#view').innerHTML=pageHead('MENU MANAGEMENT','Menu Catalog','Products, categories, pricing and ingredient recipes',`${can?'<button class="btn primary" id="addMenu">+ Add item</button>':''}`)+`<section class="panel"><div class="panel-toolbar"><input class="input" id="menuPageSearch" placeholder="Filter menu…" value="${esc(state.menuSearch)}"><div class="toolbar-group">${can?'<button class="btn ghost small" id="manageCategories">Categories</button>':''}<span class="muted">${state.menu.length} active items</span></div></div><div class="menu-grid">${filteredMenu().map((m,i)=>`<article class="menu-item photo-item static-card"><span class="food-photo food-${(m.id%6)+1}"></span><div class="menu-item-body"><span class="category-pill">${esc(m.category_name||'Uncategorized')}</span><h4>${esc(m.name)}</h4><div class="desc">${esc(m.description)}</div><div class="price">${money(m.price)}</div>${can?`<div class="row-actions"><button class="btn ghost small" data-edit-menu="${m.id}">Edit</button><button class="btn ghost small" data-recipe="${m.id}">Recipe</button><button class="btn danger small" data-archive-menu="${m.id}">Archive</button></div>`:''}</div></article>`).join('')||'<div class="empty">No menu items match.</div>'}</div></section>`;$('#menuPageSearch')?.addEventListener('input',e=>{state.menuSearch=e.target.value.trim().toLowerCase();renderMenu()});$('#addMenu')?.addEventListener('click',()=>openMenuModal());$('#manageCategories')?.addEventListener('click',openCategoryModal);document.querySelectorAll('[data-edit-menu]').forEach(b=>b.onclick=()=>openMenuModal(Number(b.dataset.editMenu)));document.querySelectorAll('[data-recipe]').forEach(b=>b.onclick=()=>openRecipeModal(Number(b.dataset.recipe)));document.querySelectorAll('[data-archive-menu]').forEach(b=>b.onclick=async()=>{if(!confirm('Archive this menu item?'))return;try{await api('/api/menu/items/delete',{method:'POST',body:JSON.stringify({id:Number(b.dataset.archiveMenu)})});await loadMenu();renderMenu();toast('Menu item archived','success')}catch(e){toast(e.message,'error')}})}
function openMenuModal(id=null){const m=id?state.menu.find(x=>x.id===id):{};showModal(`<div class="modal-top"><div><span class="eyebrow">${id?'EDIT':'NEW'} MENU ITEM</span><h3>${id?'Edit item':'Add item'}</h3></div><button class="icon-btn" data-close>×</button></div><div class="form-grid"><div class="field"><label>Name</label><input class="input" id="mName" value="${esc(m.name||'')}"></div><div class="field"><label>Price</label><input class="input" id="mPrice" type="number" step="0.01" min="0" value="${m.price??0}"></div><div class="field span-2"><label>Description</label><input class="input" id="mDesc" value="${esc(m.description||'')}"></div><div class="field"><label>Category</label><select class="select" id="mCategory"><option value="">Uncategorized</option>${state.categories.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></div><div class="field"><label>Active</label><select class="select" id="mActive"><option value="1">Yes</option><option value="0">No</option></select></div></div><div class="modal-actions"><button class="btn ghost" data-close>Cancel</button><button class="btn primary" id="saveMenu">Save item</button></div>`);$('#mCategory').value=m.category_id||'';$('#mActive').value=m.active===0?'0':'1';$('#saveMenu').onclick=async()=>{try{await api('/api/menu/items',{method:'POST',body:JSON.stringify({id,name:$('#mName').value,description:$('#mDesc').value,category_id:$('#mCategory').value?Number($('#mCategory').value):null,price:Number($('#mPrice').value),active:$('#mActive').value==='1'})});await loadMenu();closeModal();renderMenu();toast(id?'Menu item updated':'Menu item created','success')}catch(e){toast(e.message,'error')}}}
async function openCategoryModal(){const d=await api('/api/menu/all');showModal(`<div class="modal-top"><div><span class="eyebrow">MENU STRUCTURE</span><h3>Categories</h3></div><button class="icon-btn" data-close>×</button></div><div class="category-list">${d.categories.map(c=>`<div class="category-row"><span>${esc(c.name)}</span><span>${c.active?'Active':'Archived'}</span>${c.active?`<button class="btn danger small" data-cat-archive="${c.id}">Archive</button>`:''}</div>`).join('')}</div><div class="form-grid"><input class="input" id="newCatName" placeholder="New category name"><input class="input" id="newCatOrder" type="number" value="0"></div><div class="modal-actions"><button class="btn ghost" data-close>Close</button><button class="btn primary" id="saveCategory">Add category</button></div>`);$('#saveCategory').onclick=async()=>{try{await api('/api/categories',{method:'POST',body:JSON.stringify({name:$('#newCatName').value,sort_order:Number($('#newCatOrder').value)})});closeModal();openCategoryModal();await loadMenu();toast('Category added','success')}catch(e){toast(e.message,'error')}};document.querySelectorAll('[data-cat-archive]').forEach(b=>b.onclick=async()=>{try{await api('/api/categories/delete',{method:'POST',body:JSON.stringify({id:Number(b.dataset.catArchive)})});closeModal();openCategoryModal();await loadMenu();toast('Category archived','success')}catch(e){toast(e.message,'error')}})}
async function openRecipeModal(menuId){const menu=state.menu.find(m=>m.id===menuId);const d=await api(`/api/recipes?menu_item_id=${menuId}`),inv=(await api('/api/inventory')).items;showModal(`<div class="modal-top"><div><span class="eyebrow">RECIPE</span><h3>${esc(menu.name)}</h3></div><button class="icon-btn" data-close>×</button></div><div class="recipe-list">${d.recipes.map(r=>`<div class="simple-row"><span>${esc(r.item_name)} · ${num(r.quantity)} ${esc(r.unit)}</span><button class="btn danger small" data-recipe-delete="${r.id}">Remove</button></div>`).join('')||'<div class="empty">No ingredients linked yet.</div>'}</div><div class="form-grid"><select class="select" id="rItem">${inv.map(i=>`<option value="${i.id}">${esc(i.name)} · ${esc(i.unit)}</option>`).join('')}</select><input class="input" id="rQty" type="number" min="0.0001" step="0.0001" value="1"></div><div class="modal-actions"><button class="btn ghost" data-close>Close</button><button class="btn primary" id="addRecipe">Add / update ingredient</button></div>`);$('#addRecipe').onclick=async()=>{try{await api('/api/recipes',{method:'POST',body:JSON.stringify({menu_item_id:menuId,inventory_item_id:Number($('#rItem').value),quantity:Number($('#rQty').value)})});closeModal();openRecipeModal(menuId);toast('Recipe saved','success')}catch(e){toast(e.message,'error')}};document.querySelectorAll('[data-recipe-delete]').forEach(b=>b.onclick=async()=>{try{await api('/api/recipes/delete',{method:'POST',body:JSON.stringify({id:Number(b.dataset.recipeDelete)})});closeModal();openRecipeModal(menuId);toast('Ingredient removed','success')}catch(e){toast(e.message,'error')}})}
async function renderInventory(){const d=await api('/api/inventory');state.inventory=d.items;const can=roleCan('admin','manager','stock');const rows=d.items.filter(x=>!state.inventorySearch||`${x.name} ${x.sku||''}`.toLowerCase().includes(state.inventorySearch));$('#view').innerHTML=pageHead('STOCK CONTROL','Inventory','Stock levels, costs, reorder points and ingredient recipes',`${can?'<button class="btn primary" id="addStockItem">+ Add item</button>':''}`)+`<section class="panel"><div class="panel-toolbar"><input class="input" id="stockSearch" placeholder="Search stock…" value="${esc(state.inventorySearch)}"><span class="muted">${d.items.filter(x=>x.low_stock).length} low-stock alerts</span></div><div class="data-table"><div class="data-head"><span>Item</span><span>Stock</span><span>Min</span><span>Cost</span><span>State</span><span>Actions</span></div>${rows.map(x=>`<div class="data-row"><div><strong>${esc(x.name)}</strong><small>${esc(x.sku||'')} · ${esc(x.unit)}</small></div><div><strong>${num(x.current_stock)}</strong> ${esc(x.unit)}</div><div>${num(x.min_stock)}</div><div>${money(x.cost_price)}</div><div><span class="${x.low_stock?'status status-cancelled':'status status-paid'}">${x.low_stock?'LOW':'OK'}</span></div><div class="row-actions">${can?`<button class="btn ghost small" data-edit-stock="${x.id}">Edit</button><button class="btn ghost small" data-adjust-stock="${x.id}">Adjust</button>`:''}</div></div>`).join('')||'<div class="empty">No inventory items.</div>'}</div></section>`;$('#stockSearch').oninput=e=>{state.inventorySearch=e.target.value.toLowerCase();renderInventory()};$('#addStockItem')?.addEventListener('click',openNewStockModal);document.querySelectorAll('[data-adjust-stock]').forEach(b=>b.onclick=()=>openStockAdjust(Number(b.dataset.adjustStock)));document.querySelectorAll('[data-edit-stock]').forEach(b=>b.onclick=()=>openStockEdit(Number(b.dataset.editStock)))}
function openNewStockModal(){openStockEdit()}
function openStockEdit(id=null){const item=id?state.inventory.find(x=>x.id===id):{};showModal(`<div class="modal-top"><div><span class="eyebrow">${id?'EDIT':'NEW'} STOCK ITEM</span><h3>${id?'Edit inventory item':'Add inventory item'}</h3></div><button class="icon-btn" data-close>×</button></div><div class="form-grid"><div class="field"><label>SKU</label><input class="input" id="sSku" value="${esc(item.sku||'')}"></div><div class="field"><label>Name</label><input class="input" id="sName" value="${esc(item.name||'')}"></div><div class="field"><label>Unit</label><input class="input" id="sUnit" value="${esc(item.unit||'unit')}"></div><div class="field"><label>${id?'Current':'Opening'} stock</label><input class="input" id="sStock" type="number" step="0.01" value="${id?item.current_stock||0:0}" ${id?'disabled':''}></div><div class="field"><label>Minimum stock</label><input class="input" id="sMin" type="number" step="0.01" value="${item.min_stock||0}"></div><div class="field"><label>Cost price</label><input class="input" id="sCost" type="number" step="0.01" value="${item.cost_price||0}"></div></div><div class="modal-actions"><button class="btn ghost" data-close>Cancel</button><button class="btn primary" id="saveStock">${id?'Save':'Create'}</button></div>`);$('#saveStock').onclick=async()=>{try{if(id){await api('/api/inventory/items/update',{method:'POST',body:JSON.stringify({id,name:$('#sName').value,sku:$('#sSku').value,unit:$('#sUnit').value,min_stock:Number($('#sMin').value),cost_price:Number($('#sCost').value),active:true})})}else{await api('/api/inventory/items',{method:'POST',body:JSON.stringify({name:$('#sName').value,sku:$('#sSku').value,unit:$('#sUnit').value,current_stock:Number($('#sStock').value),min_stock:Number($('#sMin').value),cost_price:Number($('#sCost').value)})})}closeModal();renderInventory();toast(id?'Inventory item updated':'Inventory item created','success')}catch(e){toast(e.message,'error')}}}
function openStockAdjust(id){const item=state.inventory.find(x=>x.id===id);showModal(`<div class="modal-top"><div><span class="eyebrow">STOCK MOVEMENT</span><h3>${esc(item.name)}</h3></div><button class="icon-btn" data-close>×</button></div><p class="muted">Current stock: ${num(item.current_stock)} ${esc(item.unit)}</p><div class="field"><label>Movement</label><select class="select" id="aType"><option value="purchase">Purchase / receive</option><option value="return">Return</option><option value="adjustment">Adjustment (+ / −)</option><option value="waste">Waste</option></select></div><div class="field"><label>Quantity</label><input class="input" id="aQty" type="number" step="0.01" value="1"></div><div class="field"><label>Notes</label><input class="input" id="aNote"></div><div class="modal-actions"><button class="btn ghost" data-close>Cancel</button><button class="btn primary" id="saveAdjust">Apply</button></div>`);$('#saveAdjust').onclick=async()=>{try{let qty=Number($('#aQty').value);if($('#aType').value==='adjustment')qty=qty;await api('/api/inventory/adjust',{method:'POST',body:JSON.stringify({inventory_item_id:id,movement_type:$('#aType').value,quantity:qty,notes:$('#aNote').value})});closeModal();renderInventory();toast('Stock updated','success')}catch(e){toast(e.message,'error')}}}
async function renderPurchases(){const p=(await api('/api/purchases')).purchases,s=(await api('/api/suppliers')).suppliers;state.suppliers=s;$('#view').innerHTML=pageHead('PROCUREMENT','Purchasing','Receive stock, maintain supplier records and invoice references',`${roleCan('admin','manager','stock')?'<button class="btn primary" id="newPurchase">+ Receive purchase</button>':''}`)+`<section class="panel"><div class="panel-toolbar"><button class="btn ghost small" id="supplierBtn">Suppliers (${s.length})</button><span class="muted">${p.length} recent purchases</span></div><div class="data-table"><div class="data-head"><span>#</span><span>Supplier</span><span>Invoice</span><span>Date</span><span>Status</span><span>Total</span></div>${p.map(x=>`<div class="data-row"><div>#${x.id}</div><div>${esc(x.supplier_name||'—')}</div><div>${esc(x.invoice_no||'—')}</div><div>${esc(x.purchased_at)}</div><div><span class="status status-paid">${esc(x.status)}</span></div><div><strong>${money(x.total)}</strong></div></div>`).join('')||'<div class="empty">No purchases yet.</div>'}</div></section>`;$('#newPurchase')?.addEventListener('click',openPurchaseModal);$('#supplierBtn').onclick=openSupplierModal}
function openSupplierModal(){const s=state.suppliers;showModal(`<div class="modal-top"><div><span class="eyebrow">SUPPLIERS</span><h3>Supplier directory</h3></div><button class="icon-btn" data-close>×</button></div><div class="supplier-list">${s.map(x=>`<div class="supplier-row"><div><strong>${esc(x.name)}</strong><small>${esc(x.phone||'')} ${esc(x.email||'')}</small></div></div>`).join('')||'<div class="empty">No suppliers.</div>'}</div><div class="form-grid"><input class="input" id="supName" placeholder="Supplier name"><input class="input" id="supPhone" placeholder="Phone"><input class="input" id="supEmail" placeholder="Email"><input class="input" id="supNotes" placeholder="Notes"></div><div class="modal-actions"><button class="btn ghost" data-close>Close</button><button class="btn primary" id="saveSup">Add supplier</button></div>`);$('#saveSup').onclick=async()=>{try{await api('/api/suppliers',{method:'POST',body:JSON.stringify({name:$('#supName').value,phone:$('#supPhone').value,email:$('#supEmail').value,notes:$('#supNotes').value})});closeModal();await renderPurchases();toast('Supplier added','success')}catch(e){toast(e.message,'error')}}}
function openPurchaseModal(){if(!state.inventory.length)return toast('Add an inventory item first','error');showModal(`<div class="modal-top"><div><span class="eyebrow">RECEIVE STOCK</span><h3>New purchase</h3></div><button class="icon-btn" data-close>×</button></div><div class="field"><label>Supplier</label><select class="select" id="pSupplier"><option value="">No supplier</option>${state.suppliers.map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join('')}</select></div><div class="field"><label>Invoice no.</label><input class="input" id="pInvoice"></div><div id="purchaseLines"></div><button class="btn ghost small" id="addPurchaseLine">+ Add line</button><div class="modal-actions"><button class="btn ghost" data-close>Cancel</button><button class="btn primary" id="savePurchase">Receive</button></div>`);const lines=[{inventory_item_id:state.inventory[0].id,quantity:1,unit_cost:state.inventory[0].cost_price}];const paint=()=>{const box=$('#purchaseLines');box.innerHTML=lines.map((x,i)=>`<div class="purchase-line"><select class="select" data-pi="${i}">${state.inventory.map(it=>`<option value="${it.id}" ${it.id===x.inventory_item_id?'selected':''}>${esc(it.name)}</option>`).join('')}</select><input class="input" data-pqty="${i}" type="number" min=".01" step=".01" value="${x.quantity}"><input class="input" data-pcost="${i}" type="number" min="0" step=".01" value="${x.unit_cost}"><button class="btn danger small" data-premove="${i}">×</button></div>`).join('');box.querySelectorAll('[data-premove]').forEach(b=>b.onclick=()=>{lines.splice(+b.dataset.premove,1);paint()})};paint();$('#addPurchaseLine').onclick=()=>{lines.push({inventory_item_id:state.inventory[0].id,quantity:1,unit_cost:state.inventory[0].cost_price});paint()};$('#savePurchase').onclick=async()=>{try{const clean=[...$('#purchaseLines').querySelectorAll('.purchase-line')].map((r,i)=>({inventory_item_id:Number(r.querySelector(`[data-pi="${i}"]`).value),quantity:Number(r.querySelector(`[data-pqty="${i}"]`).value),unit_cost:Number(r.querySelector(`[data-pcost="${i}"]`).value)}));await api('/api/purchases',{method:'POST',body:JSON.stringify({supplier_id:$('#pSupplier').value?Number($('#pSupplier').value):null,invoice_no:$('#pInvoice').value,items:clean})});closeModal();renderPurchases();toast('Purchase received','success')}catch(e){toast(e.message,'error')}}}
async function renderExpenses(){const d=(await api('/api/expenses')).expenses;state.expenses=d;$('#view').innerHTML=pageHead('OPERATING COSTS','Expenses','Record utilities, rent, payroll advances and other operating costs','<button class="btn primary" id="newExpense">+ Add expense</button>')+`<section class="panel"><div class="data-table"><div class="data-head"><span>Date</span><span>Category</span><span>Description</span><span>Paid</span><span>Amount</span><span></span></div>${d.map(x=>`<div class="data-row"><div>${esc(x.expense_date)}</div><div>${esc(x.category)}</div><div><strong>${esc(x.description)}</strong><small>${esc(x.notes||'')}</small></div><div>${x.paid?'Yes':'No'}</div><div><strong>${money(x.amount)}</strong></div><div></div></div>`).join('')||'<div class="empty">No expenses yet.</div>'}</div></section>`;$('#newExpense').onclick=openExpenseModal}
function openExpenseModal(){showModal(`<div class="modal-top"><div><span class="eyebrow">NEW EXPENSE</span><h3>Record operating cost</h3></div><button class="icon-btn" data-close>×</button></div><div class="form-grid"><div class="field"><label>Category</label><input class="input" id="eCat" value="General"></div><div class="field"><label>Amount</label><input class="input" id="eAmt" type="number" min="0.01" step="0.01"></div><div class="field span-2"><label>Description</label><input class="input" id="eDesc"></div><div class="field"><label>Date</label><input class="input" id="eDate" type="date" value="${today()}"></div><div class="field"><label>Paid</label><select class="select" id="ePaid"><option value="1">Yes</option><option value="0">No</option></select></div><div class="field span-2"><label>Notes</label><input class="input" id="eNotes"></div></div><div class="modal-actions"><button class="btn ghost" data-close>Cancel</button><button class="btn primary" id="saveExpense">Save</button></div>`);$('#saveExpense').onclick=async()=>{try{await api('/api/expenses',{method:'POST',body:JSON.stringify({category:$('#eCat').value,amount:Number($('#eAmt').value),description:$('#eDesc').value,expense_date:$('#eDate').value,paid:$('#ePaid').value==='1',notes:$('#eNotes').value})});closeModal();renderExpenses();toast('Expense recorded','success')}catch(e){toast(e.message,'error')}}}
async function renderPayments(){const d=(await api('/api/payments')).payments;state.payments=d;if(!state.orders.length)await loadOrders();const pending=state.orders.filter(o=>!['paid','cancelled'].includes(o.status));$('#view').innerHTML=pageHead('CASHIER','Payments','Collect order balances and review payment history','<button class="btn primary" id="newPayment">+ Record payment</button>')+`<section class="panel"><div class="panel-toolbar"><div class="toolbar-group"><strong>${d.length}</strong><span class="muted">payments logged</span></div><span class="muted">Pending orders: ${pending.length}</span></div><div class="data-table"><div class="data-head"><span>Date</span><span>Order</span><span>Method</span><span>Reference</span><span>Amount</span><span></span></div>${d.map(x=>`<div class="data-row"><div>${fmtDate(x.paid_at)}</div><div>${x.order_id?`#${x.order_id}`:'External'}</div><div>${esc(x.payment_method)}</div><div>${esc(x.reference||'—')}</div><div><strong>${money(x.amount)}</strong></div><div></div></div>`).join('')||'<div class="empty">No payments yet.</div>'}</div></section>`;$('#newPayment').onclick=()=>openPaymentModal(state.orders)}
function openPaymentModal(orders,selectedId=null){const candidates=orders.filter(o=>!['paid','cancelled'].includes(o.status));showModal(`<div class="modal-top"><div><span class="eyebrow">COLLECT PAYMENT</span><h3>Record payment</h3></div><button class="icon-btn" data-close>×</button></div><div class="field"><label>Order</label><select class="select" id="payOrder"><option value="">External / no order</option>${candidates.map(o=>`<option value="${o.id}" ${o.id===selectedId?'selected':''}>#${o.id} · ${esc(o.table_no||'Takeaway')} · ${money(Number(o.total)-Number(o.paid_amount||0))} remaining</option>`).join('')}</select></div><div class="field"><label>Method</label><select class="select" id="payMethod"><option>cash</option><option>card</option><option>transfer</option><option>other</option></select></div><div class="field"><label>Amount</label><input class="input" id="payAmount" type="number" min="0.01" step="0.01"></div><div class="field"><label>Reference</label><input class="input" id="payRef"></div><div class="field"><label>Notes</label><input class="input" id="payNotes"></div><div class="modal-actions"><button class="btn ghost" data-close>Cancel</button><button class="btn primary" id="savePayment">Record</button></div>`);const update=()=>{const o=orders.find(x=>x.id===Number($('#payOrder').value));$('#payAmount').value=o?Math.max(0,Number(o.total)-Number(o.paid_amount||0)).toFixed(2):''};$('#payOrder').onchange=update;update();$('#savePayment').onclick=async()=>{try{await api('/api/payments',{method:'POST',body:JSON.stringify({order_id:$('#payOrder').value?Number($('#payOrder').value):null,payment_method:$('#payMethod').value,amount:Number($('#payAmount').value),reference:$('#payRef').value,notes:$('#payNotes').value})});closeModal();await refreshCore();renderPayments();successSound();toast('Payment recorded','success')}catch(e){toast(e.message,'error')}}}
async function renderCash(){const d=await api('/api/cash'),c=d.current;const expected=d.expected_cash;$('#view').innerHTML=pageHead('FINANCE CONTROL','Cash Register','Open the register, reconcile cash and close the session',`${c?'':'<button class="btn primary" id="openCash">Open register</button>'}`)+`<div class="report-grid"><div class="report-card"><span>Session</span><strong>${c?'OPEN':'CLOSED'}</strong></div><div class="report-card"><span>Cash sales today</span><strong>${money(d.today_cash_sales)}</strong></div><div class="report-card"><span>Cash expenses today</span><strong>${money(d.today_cash_expenses)}</strong></div><div class="report-card"><span>Expected cash</span><strong>${money(expected)}</strong></div></div><section class="panel">${c?`<div class="cash-summary"><div><span>Opened</span><strong>${fmtDate(c.opened_at)}</strong></div><div><span>Opening float</span><strong>${money(c.opening_amount)}</strong></div><div><span>Operator</span><strong>${esc(state.user.display_name)}</strong></div></div><div class="modal-actions"><button class="btn primary" id="closeCash">Close register</button></div>`:'<div class="empty">No open register session. Open one before handling a cash shift.</div>'}</section>`;$('#openCash')?.addEventListener('click',openCashModal);$('#closeCash')?.addEventListener('click',()=>openCloseCashModal(d))}
function openCashModal(){showModal(`<div class="modal-top"><div><span class="eyebrow">OPEN SHIFT</span><h3>Open cash register</h3></div><button class="icon-btn" data-close>×</button></div><div class="field"><label>Opening amount</label><input class="input" id="openingCash" type="number" min="0" step="0.01" value="0"></div><div class="field"><label>Notes</label><input class="input" id="openingNotes"></div><div class="modal-actions"><button class="btn ghost" data-close>Cancel</button><button class="btn primary" id="saveOpenCash">Open register</button></div>`);$('#saveOpenCash').onclick=async()=>{try{await api('/api/cash/open',{method:'POST',body:JSON.stringify({opening_amount:Number($('#openingCash').value),notes:$('#openingNotes').value})});closeModal();renderCash();toast('Cash register opened','success')}catch(e){toast(e.message,'error')}}}
function openCloseCashModal(d){showModal(`<div class="modal-top"><div><span class="eyebrow">CLOSE SHIFT</span><h3>Reconcile cash</h3></div><button class="icon-btn" data-close>×</button></div><p class="muted">Expected cash: <strong>${money(d.expected_cash)}</strong></p><div class="field"><label>Counted cash</label><input class="input" id="closingCash" type="number" step="0.01" value="${Number(d.expected_cash).toFixed(2)}"></div><div class="field"><label>Notes</label><input class="input" id="closingNotes"></div><div class="modal-actions"><button class="btn ghost" data-close>Cancel</button><button class="btn primary" id="saveCloseCash">Close register</button></div>`);$('#saveCloseCash').onclick=async()=>{try{const x=await api('/api/cash/close',{method:'POST',body:JSON.stringify({closing_amount:Number($('#closingCash').value),notes:$('#closingNotes').value})});closeModal();renderCash();toast(`Register closed · difference ${money(x.difference)}`,'success')}catch(e){toast(e.message,'error')}}}
async function renderDebts(){const d=await api('/api/debts'),rows=d.debts;const receivable=rows.filter(x=>x.debt_type==='receivable').reduce((s,x)=>s+Number(x.remaining),0),payable=rows.filter(x=>x.debt_type==='payable').reduce((s,x)=>s+Number(x.remaining),0);$('#view').innerHTML=pageHead('FINANCE','Debts & Outstanding','Track customer receivables and supplier/payable balances',`${roleCan('admin','manager','cashier','stock')?'<button class="btn primary" id="addDebt">+ Add debt</button>':''}`)+`<div class="report-grid"><div class="report-card"><span>Receivables</span><strong>${money(receivable)}</strong></div><div class="report-card"><span>Payables</span><strong>${money(payable)}</strong></div><div class="report-card"><span>Open records</span><strong>${rows.filter(x=>Number(x.remaining)>0).length}</strong></div><div class="report-card"><span>Settled</span><strong>${rows.filter(x=>Number(x.remaining)<=0).length}</strong></div></div><section class="panel"><div class="data-table"><div class="data-head"><span>Type</span><span>Party</span><span>Reference</span><span>Due</span><span>Remaining</span><span>Actions</span></div>${rows.map(x=>`<div class="data-row"><div><span class="role-badge">${esc(x.debt_type)}</span></div><div><strong>${esc(x.party_name)}</strong><small>${esc(x.notes||'')}</small></div><div>${esc(x.reference||'—')}</div><div>${esc(x.due_date||'—')}</div><div><strong>${money(x.remaining)}</strong><small>Paid ${money(x.paid_amount)} / ${money(x.amount)}</small></div><div class="row-actions">${Number(x.remaining)>0?`<button class="btn primary small" data-debt-pay="${x.id}">Pay</button>`:''}<button class="btn ghost small" data-debt-archive="${x.id}">Archive</button></div></div>`).join('')||'<div class="empty">No debts recorded.</div>'}</div></section>`;$('#addDebt')?.addEventListener('click',openDebtModal);document.querySelectorAll('[data-debt-pay]').forEach(b=>b.onclick=()=>openDebtPaymentModal(Number(b.dataset.debtPay),rows));document.querySelectorAll('[data-debt-archive]').forEach(b=>b.onclick=async()=>{try{await api('/api/debts/archive',{method:'POST',body:JSON.stringify({id:Number(b.dataset.debtArchive)})});renderDebts();toast('Debt archived','success')}catch(e){toast(e.message,'error')}})}
function openDebtModal(){showModal(`<div class="modal-top"><div><span class="eyebrow">NEW DEBT</span><h3>Record outstanding balance</h3></div><button class="icon-btn" data-close>×</button></div><div class="form-grid"><div class="field"><label>Type</label><select class="select" id="dType"><option value="receivable">Receivable</option><option value="payable">Payable</option></select></div><div class="field"><label>Party</label><input class="input" id="dParty"></div><div class="field"><label>Amount</label><input class="input" id="dAmount" type="number" min="0.01" step="0.01"></div><div class="field"><label>Due date</label><input class="input" id="dDue" type="date"></div><div class="field"><label>Reference</label><input class="input" id="dRef"></div><div class="field span-2"><label>Notes</label><input class="input" id="dNotes"></div></div><div class="modal-actions"><button class="btn ghost" data-close>Cancel</button><button class="btn primary" id="saveDebt">Save debt</button></div>`);$('#saveDebt').onclick=async()=>{try{await api('/api/debts',{method:'POST',body:JSON.stringify({debt_type:$('#dType').value,party_name:$('#dParty').value,amount:Number($('#dAmount').value),due_date:$('#dDue').value,reference:$('#dRef').value,notes:$('#dNotes').value})});closeModal();renderDebts();toast('Debt recorded','success')}catch(e){toast(e.message,'error')}}}
function openDebtPaymentModal(id,rows){const d=rows.find(x=>x.id===id);showModal(`<div class="modal-top"><div><span class="eyebrow">SETTLEMENT</span><h3>${esc(d.party_name)}</h3></div><button class="icon-btn" data-close>×</button></div><p class="muted">Remaining balance: <strong>${money(d.remaining)}</strong></p><div class="field"><label>Payment amount</label><input class="input" id="dpAmount" type="number" min="0.01" max="${d.remaining}" step="0.01" value="${Number(d.remaining).toFixed(2)}"></div><div class="modal-actions"><button class="btn ghost" data-close>Cancel</button><button class="btn primary" id="settleDebt">Apply payment</button></div>`);$('#settleDebt').onclick=async()=>{try{await api('/api/debts/payment',{method:'POST',body:JSON.stringify({id,amount:Number($('#dpAmount').value)})});closeModal();renderDebts();toast('Debt payment applied','success')}catch(e){toast(e.message,'error')}}}

async function renderReports(){const now=new Date();if(!state.reportFrom)state.reportFrom=new Date(now.getFullYear(),now.getMonth(),1).toISOString().slice(0,10);if(!state.reportTo)state.reportTo=today();const d=await api(`/api/reports/summary?from=${encodeURIComponent(state.reportFrom)}&to=${encodeURIComponent(state.reportTo)}`);const max=Math.max(1,...d.daily.map(x=>Number(x.sales)));$('#view').innerHTML=pageHead('MANAGEMENT REPORTING','Sales & profitability','Filter the period and separate sales, COGS and operating costs',`<button class="btn ghost" id="applyReport">Apply</button>`)+`<section class="panel report-filters"><div class="form-grid"><div class="field"><label>From</label><input class="input" id="rFrom" type="date" value="${state.reportFrom}"></div><div class="field"><label>To</label><input class="input" id="rTo" type="date" value="${state.reportTo}"></div></div></section><div class="report-grid"><div class="report-card"><span>Sales</span><strong>${money(d.summary.sales)}</strong></div><div class="report-card"><span>COGS (recipe cost)</span><strong>${money(d.summary.cogs)}</strong></div><div class="report-card"><span>Gross profit</span><strong>${money(d.summary.gross_profit)}</strong></div><div class="report-card"><span>Operating profit</span><strong>${money(d.summary.operating_profit)}</strong></div><div class="report-card"><span>Expenses</span><strong>${money(d.summary.expenses)}</strong></div><div class="report-card"><span>Purchases</span><strong>${money(d.summary.purchases)}</strong></div><div class="report-card"><span>Orders</span><strong>${d.summary.orders}</strong></div><div class="report-card"><span>Net cash-style view</span><strong>${money(d.summary.net)}</strong></div></div><section class="panel"><div class="panel-head"><div><span class="eyebrow">DAILY SALES</span><h3>Sales trend</h3></div><div class="row-actions"><button class="btn ghost small" id="printReport">Print</button><button class="btn ghost small" id="exportReport">Export CSV</button></div></div><div class="sales-chart">${d.daily.length?d.daily.map(x=>`<div class="sales-bar"><span class="sales-value">${money(x.sales)}</span><div class="bar-track"><i style="height:${Math.max(8,(Number(x.sales)/max)*100)}%"></i></div><small>${esc(x.day.slice(5))}</small></div>`).join(''):'<div class="empty">No paid sales in this period.</div>'}</div></section><section class="panel"><div class="panel-head"><div><span class="eyebrow">PAYMENT MIX</span><h3>Collected by method</h3></div></div>${d.methods.length?d.methods.map(x=>`<div class="simple-row"><span>${esc(x.payment_method)} <small class="muted">(${x.count})</small></span><strong>${money(x.total)}</strong></div>`).join(''):'<div class="empty">No payments in period.</div>'}</section><section class="panel"><div class="panel-head"><div><span class="eyebrow">TOP ITEMS</span><h3>Paid sales</h3></div></div>${d.top_items.length?d.top_items.map(x=>`<div class="simple-row"><span>${esc(x.name)} <small class="muted">× ${x.qty}</small></span><strong>${money(x.sales)}</strong></div>`).join(''):'<div class="empty">No paid orders in period.</div>'}</section>`;$('#applyReport').onclick=()=>{state.reportFrom=$('#rFrom').value;state.reportTo=$('#rTo').value;renderReports()};$('#printReport').onclick=()=>window.print();$('#exportReport').onclick=()=>{const rows=[['Metric','Value'],['Sales',d.summary.sales],['COGS',d.summary.cogs],['Gross Profit',d.summary.gross_profit],['Operating Profit',d.summary.operating_profit],['Expenses',d.summary.expenses],['Purchases',d.summary.purchases],['Orders',d.summary.orders],['Net',d.summary.net],[],['Day','Sales','Orders'],...d.daily.map(x=>[x.day,x.sales,x.orders]),[],['Payment Method','Amount','Count'],...d.methods.map(x=>[x.payment_method,x.total,x.count])];const csv=rows.map(r=>r.map(v=>`"${String(v??'').replaceAll('"','""')}"`).join(',')).join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download=`restaurantos-report-${state.reportFrom}-${state.reportTo}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)} }
async function renderReservations(){const d=await api(`/api/reservations?date=${encodeURIComponent(state.reservationDate)}`),customers=(await api('/api/customers')).customers;state.reservations=d.reservations;state.customers=customers;const can=roleCan('admin','manager','cashier');$('#view').innerHTML=pageHead('RESERVATIONS','Reservations','Book tables, track arrivals and manage no-shows',`${can?'<button class="btn primary" id="addReservation">+ New reservation</button>':''}`)+`<section class="panel"><div class="panel-toolbar"><input class="input" id="resDate" type="date" value="${state.reservationDate}"><span class="muted">${d.reservations.length} reservations</span></div><div class="data-table"><div class="data-head"><span>Time</span><span>Customer</span><span>Guests</span><span>Table</span><span>Status</span><span>Actions</span></div>${d.reservations.map(r=>`<div class="data-row"><div><strong>${esc(r.reservation_time)}</strong></div><div><strong>${esc(r.customer_name||'Walk-in')}</strong><small>${esc(r.phone||'')}</small></div><div>${r.guests}</div><div>${esc(r.table_no||'Unassigned')}</div><div><span class="${statusClass(r.status)}">${esc(r.status)}</span></div><div><select class="select compact-select" data-res-status="${r.id}">${['booked','confirmed','seated','completed','cancelled','no-show'].map(x=>`<option ${r.status===x?'selected':''}>${x}</option>`).join('')}</select></div></div>`).join('')||'<div class="empty">No reservations for this date.</div>'}</div></section>`;$('#resDate').onchange=e=>{state.reservationDate=e.target.value;renderReservations()};$('#addReservation')?.addEventListener('click',()=>openReservationModal(customers));document.querySelectorAll('[data-res-status]').forEach(s=>s.onchange=async()=>{try{await api('/api/reservations/status',{method:'POST',body:JSON.stringify({id:Number(s.dataset.resStatus),status:s.value})});successSound();toast('Reservation updated','success')}catch(e){toast(e.message,'error')}})}
function openReservationModal(customers){showModal(`<div class="modal-top"><div><span class="eyebrow">NEW RESERVATION</span><h3>Book a table</h3></div><button class="icon-btn" data-close>×</button></div><div class="form-grid"><div class="field"><label>Customer</label><select class="select" id="resCustomer"><option value="">Walk-in / new</option>${customers.map(c=>`<option value="${c.id}">${esc(c.name)} · ${esc(c.phone||'')}</option>`).join('')}</select></div><div class="field"><label>Table</label><select class="select" id="resTable"><option value="">Unassigned</option>${state.tables.map(t=>`<option value="${t.id}">${esc(t.table_no)} · ${t.seats} seats</option>`).join('')}</select></div><div class="field"><label>Date</label><input class="input" id="resDateM" type="date" value="${state.reservationDate}"></div><div class="field"><label>Time</label><input class="input" id="resTime" type="time" value="19:00"></div><div class="field"><label>Guests</label><input class="input" id="resGuests" type="number" min="1" value="2"></div><div class="field span-2"><label>Notes</label><input class="input" id="resNotes"></div></div><div class="modal-actions"><button class="btn ghost" data-close>Cancel</button><button class="btn primary" id="saveReservation">Book</button></div>`);$('#saveReservation').onclick=async()=>{try{let customerId=$('#resCustomer').value?Number($('#resCustomer').value):null;if(!customerId){const name=prompt('Customer name');if(name){const c=await api('/api/customers',{method:'POST',body:JSON.stringify({name})});customerId=c.id}}await api('/api/reservations',{method:'POST',body:JSON.stringify({customer_id:customerId,table_id:$('#resTable').value?Number($('#resTable').value):null,reservation_date:$('#resDateM').value,reservation_time:$('#resTime').value,guests:Number($('#resGuests').value),notes:$('#resNotes').value})});closeModal();state.reservationDate=$('#resDateM').value;renderReservations();toast('Reservation created','success')}catch(e){toast(e.message,'error')}}}
async function renderCustomers(){const d=await api('/api/customers');state.customers=d.customers;const can=roleCan('admin','manager','cashier');const q=state.menuSearch;const rows=d.customers.filter(c=>!q||`${c.name} ${c.phone} ${c.email}`.toLowerCase().includes(q));$('#view').innerHTML=pageHead('CRM','Customers','Customer directory, contacts and lifetime spending',`${can?'<button class="btn primary" id="addCustomer">+ Add customer</button>':''}`)+`<section class="panel"><div class="panel-toolbar"><input class="input" id="custSearch" placeholder="Search customers…" value="${esc(q)}"><span class="muted">${rows.length} customers</span></div><div class="data-table"><div class="data-head"><span>Customer</span><span>Phone</span><span>Email</span><span>Orders</span><span>Spent</span><span>Actions</span></div>${rows.map(c=>`<div class="data-row"><div><strong>${esc(c.name)}</strong><small>${esc(c.notes||'')}</small></div><div>${esc(c.phone||'—')}</div><div>${esc(c.email||'—')}</div><div>${c.order_count||0}</div><div>${money(c.spent)}</div><div>${can?`<button class="btn ghost small" data-edit-customer="${c.id}">Edit</button>`:''}</div></div>`).join('')||'<div class="empty">No customers.</div>'}</div></section>`;$('#custSearch').oninput=e=>{state.menuSearch=e.target.value.toLowerCase();renderCustomers()};$('#addCustomer')?.addEventListener('click',()=>openCustomerModal());document.querySelectorAll('[data-edit-customer]').forEach(b=>b.onclick=()=>openCustomerModal(Number(b.dataset.editCustomer)))}
function openCustomerModal(id=null){const c=id?state.customers.find(x=>x.id===id):{};showModal(`<div class="modal-top"><div><span class="eyebrow">CUSTOMER</span><h3>${id?'Edit customer':'New customer'}</h3></div><button class="icon-btn" data-close>×</button></div><div class="form-grid"><div class="field"><label>Name</label><input class="input" id="cName" value="${esc(c.name||'')}"></div><div class="field"><label>Phone</label><input class="input" id="cPhone" value="${esc(c.phone||'')}"></div><div class="field"><label>Email</label><input class="input" id="cEmail" value="${esc(c.email||'')}"></div><div class="field span-2"><label>Notes</label><input class="input" id="cNotes" value="${esc(c.notes||'')}"></div></div><div class="modal-actions"><button class="btn danger" id="archiveCustomer" style="display:${id?'inline-flex':'none'}">Archive</button><button class="btn ghost" data-close>Cancel</button><button class="btn primary" id="saveCustomer">Save</button></div>`);$('#saveCustomer').onclick=async()=>{try{await api('/api/customers',{method:'POST',body:JSON.stringify({id,name:$('#cName').value,phone:$('#cPhone').value,email:$('#cEmail').value,notes:$('#cNotes').value})});closeModal();renderCustomers();toast(id?'Customer updated':'Customer created','success')}catch(e){toast(e.message,'error')}};$('#archiveCustomer').onclick=async()=>{try{await api('/api/customers/delete',{method:'POST',body:JSON.stringify({id})});closeModal();renderCustomers();toast('Customer archived','success')}catch(e){toast(e.message,'error')}}}
async function renderStaff(){if(state.user?.role!=='admin'){return forbidden('Admin access is required for staff management.')}const d=await api('/api/users');state.users=d.users;$('#view').innerHTML=pageHead('ACCESS CONTROL','Staff & Roles','Manage accounts, roles and active status','<button class="btn primary" id="addStaff">+ Add staff</button>')+`<section class="panel"><div class="data-table"><div class="data-head"><span>User</span><span>Email</span><span>Role</span><span>Status</span><span>Created</span><span>Actions</span></div>${d.users.map(u=>`<div class="data-row"><div><strong>${esc(u.display_name)}</strong></div><div>${esc(u.email)}</div><div><span class="role-badge">${esc(u.role)}</span></div><div>${u.active?'Active':'Inactive'}</div><div>${fmtDate(u.created_at)}</div><div><button class="btn ghost small" data-edit-user="${u.id}">Edit</button></div></div>`).join('')}</div></section>`;$('#addStaff').onclick=()=>openStaffModal();document.querySelectorAll('[data-edit-user]').forEach(b=>b.onclick=()=>openStaffModal(Number(b.dataset.editUser)))}
function forbidden(msg){$('#view').innerHTML=`<section class="panel forbidden"><div class="empty"><span>🛡</span><h3>Access restricted</h3><p>${esc(msg)}</p></div></section>`}
function openStaffModal(id=null){const u=id?state.users.find(x=>x.id===id):{};showModal(`<div class="modal-top"><div><span class="eyebrow">STAFF ACCOUNT</span><h3>${id?'Edit account':'New account'}</h3></div><button class="icon-btn" data-close>×</button></div><div class="form-grid"><div class="field"><label>Display name</label><input class="input" id="uName" value="${esc(u.display_name||'')}"></div><div class="field"><label>Email</label><input class="input" id="uEmail" value="${esc(u.email||'')}" ${id?'disabled':''}></div><div class="field"><label>Role</label><select class="select" id="uRole">${['cashier','stock','manager','admin'].map(x=>`<option ${u.role===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Status</label><select class="select" id="uActive"><option value="1" ${u.active?'selected':''}>Active</option><option value="0" ${u.active?'':'selected'}>Inactive</option></select></div><div class="field span-2"><label>${id?'Reset password (optional)':'Password'}</label><input class="input" id="uPass" type="password" placeholder="8+ characters"></div></div><div class="modal-actions"><button class="btn ghost" data-close>Cancel</button><button class="btn primary" id="saveUser">Save account</button></div>`);$('#saveUser').onclick=async()=>{try{if(id){await api('/api/users/update',{method:'POST',body:JSON.stringify({id,display_name:$('#uName').value,role:$('#uRole').value,active:$('#uActive').value==='1',password:$('#uPass').value})})}else{await api('/api/users',{method:'POST',body:JSON.stringify({display_name:$('#uName').value,email:$('#uEmail').value,password:$('#uPass').value,role:$('#uRole').value})})}closeModal();renderStaff();toast('Staff account saved','success')}catch(e){toast(e.message,'error')}}}
async function renderAudit(){if(!roleCan('admin','manager'))return forbidden('Manager or admin access is required for audit logs.');const d=await api('/api/audit');$('#view').innerHTML=pageHead('SECURITY','Audit Log','Chronological record of key operational changes')+`<section class="panel"><div class="data-table"><div class="data-head audit-head"><span>Date</span><span>Action</span><span>Entity</span><span>ID</span><span>Details</span><span></span></div>${d.logs.map(x=>`<div class="data-row audit-row"><div>${fmtDate(x.created_at)}</div><div><span class="role-badge">${esc(x.action)}</span></div><div>${esc(x.entity)}</div><div>${x.entity_id??'—'}</div><div>${esc(x.details||'')}</div><div></div></div>`).join('')||'<div class="empty">No audit entries.</div>'}</div></section>`}
async function renderSettings(){const d=await api('/api/settings');state.settings=d.settings;const can=roleCan('admin','manager');$('#view').innerHTML=pageHead('SYSTEM','Settings','Restaurant identity, tax, receipt text, theme and database safety',`${can?'<button class="btn primary" id="saveSettings">Save settings</button>':''}`)+`<section class="panel"><div class="form-grid"><div class="field"><label>Restaurant name</label><input class="input" id="setName" value="${esc(state.settings.restaurant_name||'')}"></div><div class="field"><label>Currency</label><input class="input" id="setCurrency" value="${esc(state.settings.currency||'DZD')}"></div><div class="field"><label>Tax rate (%)</label><input class="input" id="setTax" type="number" step="0.01" min="0" value="${esc(state.settings.tax_rate||0)}"></div><div class="field"><label>Phone</label><input class="input" id="setPhone" value="${esc(state.settings.phone||'')}"></div><div class="field span-2"><label>Address</label><input class="input" id="setAddress" value="${esc(state.settings.address||'')}"></div><div class="field span-2"><label>Receipt footer</label><input class="input" id="setFooter" value="${esc(state.settings.receipt_footer||'')}"></div></div></section><section class="panel"><div class="panel-head"><div><span class="eyebrow">APPEARANCE</span><h3>Theme & sound</h3></div></div><div class="settings-actions"><button class="btn ghost" id="toggleTheme2">${state.theme==='light'?'☀ Light':'☾ Dark'} theme</button><button class="btn ghost" id="testSound">🔊 Test sound</button></div></section><section class="panel"><div class="panel-head"><div><span class="eyebrow">DATABASE SAFETY</span><h3>Backup</h3></div></div><p class="muted">Create a timestamped SQLite backup before major changes or closing the day.</p><button class="btn ghost" id="backupBtn" ${state.user?.role==='admin'?'':'disabled'}>Create database backup</button></section>`;$('#saveSettings')?.addEventListener('click',async()=>{try{const data=await api('/api/settings',{method:'POST',body:JSON.stringify({settings:{restaurant_name:$('#setName').value,currency:$('#setCurrency').value,tax_rate:$('#setTax').value,phone:$('#setPhone').value,address:$('#setAddress').value,receipt_footer:$('#setFooter').value}})});state.settings=data.settings;renderShell();toast('Settings saved','success')}catch(e){toast(e.message,'error')}});$('#toggleTheme2').onclick=()=>{state.theme=state.theme==='light'?'dark':'light';localStorage.setItem('restaurantos_theme',state.theme);applyTheme();renderSettings()};$('#testSound').onclick=()=>{ensureAudio();successSound()};$('#backupBtn')?.addEventListener('click',async()=>{try{const d=await api('/api/backup');const res=await fetch(d.url,{headers:{'X-Session-Token':token}});if(!res.ok)throw new Error('Backup download failed');const blob=await res.blob();const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=d.filename;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('Backup created','success')}catch(e){toast(e.message,'error')}})}
async function startOrderWatcher(){if(state.watcherStarted)return;state.watcherStarted=true;state.lastReadyOrders=new Set((state.dashboard?.recent||[]).filter(x=>x.status==='ready').map(x=>x.id));setInterval(async()=>{if(!token)return;try{const d=await api('/api/dashboard'),ready=new Set((d.recent||[]).filter(x=>x.status==='ready').map(x=>x.id));for(const id of ready)if(!state.lastReadyOrders.has(id)){orderSound();toast(`Order #${id} is ready`,'success');break}state.lastReadyOrders=ready;state.dashboard=d;if(state.activeView==='dashboard')renderDashboard()}catch(_e){}},7000)}
if(token)loadApp().catch(()=>{token='';localStorage.removeItem('restaurantos_token');state.user=null;renderLogin()});else renderLogin();
